/**
 * JMA class10 warning-area geometry — generated, do not hand-edit.
 *
 * Generated by `scripts/generate-jma-areas.mjs`. Regenerate with:
 *   npm run generate:jma-areas
 *
 * Sources:
 *   - https://www.jma.go.jp/bosai/common/const/geojson/class10s.json
 *   - https://www.jma.go.jp/bosai/common/const/area.json
 * Generated: 2026-09-03
 *
 * Ring coordinates are `[lat, lon]` pairs (swapped from GeoJSON's
 * `[lon, lat]` order) to match `pointInAnyRing` in
 * `src/utils/pointInPolygon.ts`. Rounded to 3 decimal places (~110 m);
 * consecutive duplicate points (an artifact of rounding) are dropped.
 * Outer rings only — the source feed has zero interior rings.
 *
 * `officeCode` is undefined for exactly one area (code `hoppo`), which has
 * no entry in the upstream area.json and therefore no issuing office.
 *
 * TWO NAMING TRAPS FOR ANY RENDERER READING THIS DATA:
 *   1. `hoppo` carries upstream's own map label, which is byte-identical
 *      to real area 014010 ("根室地方" / "Nemuro"). 014010 has an issuing
 *      office and does receive warnings. Rendering `hoppo`'s name beside a
 *      "no issuing office" note therefore states something false about
 *      014010. Key the no-office case off `officeCode === undefined` and do
 *      not print the name for it.
 *   2. Names are NOT unique. "北部" / "Northern Region" appears 17 times and
 *      "南部" / "Southern Region" 18 times — they are prefecture sub-region
 *      labels, meaningful only beside their parent office. Never present a
 *      bare area name as if it identified a place.
 */

/** One class10 JMA warning area. */
export interface JmaClass10Area {
  /** class10 area code, e.g. "130010". */
  readonly code: string;
  /** Japanese name, e.g. "東京地方". */
  readonly name: string;
  /** English name, e.g. "Tokyo Region". */
  readonly enName: string;
  /** Parent JMA office code. Undefined for the one area with no issuing office. */
  readonly officeCode?: string;
  /** Outer-ring polygons, each a list of [lat, lon] pairs. */
  readonly rings: ReadonlyArray<ReadonlyArray<readonly [number, number]>>;
}

